import { NextResponse } from 'next/server';

function verifyRazorpaySignature(
  razorPayOrderId: string,
  razorPayPaymentId: string,
  razorPaySignature: string
): boolean {
  // In a real implementation, you would verify the Razorpay signature using
  // your Razorpay Key Secret from environment variables.
  // The signature is generated by: crypto.createHmac('sha256', secret)
  // .update(razorPayOrderId + '|' + razorPayPaymentId, 'utf8')
  // .digest('hex')

  // For this demo, we accept any non-empty signature
  return !!(
    razorPayOrderId &&
    razorPayPaymentId &&
    razorPaySignature &&
    razorPaySignature.length > 0
  );
}

export async function POST(request: Request) {
  try {
    const { razorpay_order_id, razorpay_payment_id, razorpay_signature } =
      await request.json();

    if (!razorpay_order_id || !razorpay_payment_id || !razorpay_signature) {
      return NextResponse.json(
        { error: 'Missing required parameters' },
        { status: 400 }
      );
    }

    // Verify the signature
    const isValid = verifyRazorpaySignature(
      razorpay_order_id,
      razorpay_payment_id,
      razorpay_signature
    );

    if (isValid) {
      // Update payment status in database
      // In a real implementation, you would update the Payment record
      // associated with the order

      return NextResponse.json({
        status: 'verified',
        message: 'Payment verified successfully',
      });
    } else {
      return NextResponse.json(
        { error: 'Invalid Razorpay signature' },
        { status: 400 }
      );
    }
  } catch (error) {
    console.error('[POST /api/payment/razorpay/verify]', error);
    return NextResponse.json(
      { error: 'Failed to verify payment' },
      { status: 500 }
    );
  }
}